const D = { petals:6, step:71, energy:.7, scale:1, density:.6, speed:1, hue:285, x:.5, y:.5, style:'spectral', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const DEG = Math.PI / 180;
const u = Math.min(width, height);
const style = P.style;
const wh = h => ((h % 360) + 360) % 360;
function hcss(h, s, b, a) {
  h = wh(h); s = s / 100; b = b / 100;
  const c = b * s, x = c * (1 - Math.abs(((h / 60) % 2) - 1)), mm = b - c;
  let r, g2, bl;
  if (h < 60) { r = c; g2 = x; bl = 0; } else if (h < 120) { r = x; g2 = c; bl = 0; }
  else if (h < 180) { r = 0; g2 = c; bl = x; } else if (h < 240) { r = 0; g2 = x; bl = c; }
  else if (h < 300) { r = x; g2 = 0; bl = c; } else { r = c; g2 = 0; bl = x; }
  return 'rgba(' + ((r + mm) * 255 | 0) + ',' + ((g2 + mm) * 255 | 0) + ',' + ((bl + mm) * 255 | 0) + ',' + a + ')';
}

// seed-dependent variation (inline hash, not p5 random)
if (S.seedUsed !== P.seed) {
  S.seedUsed = P.seed;
  const fr = i => { const s = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return s - Math.floor(s); };
  S.hoff = fr(1) * 60;
  S.spin = fr(2) < .5 ? -1 : 1;
  S.dph1 = fr(3) * TAU; S.dph2 = fr(4) * TAU;
  S.nph = fr(5) * TAU;
  S.dEx = (fr(6) - .5) * 6;
  S.nEx = (fr(7) - .5) * 1.2;
  S.hueSpread = 210 + fr(8) * 130;
}

// radial glow sprite (grayscale, built once, size-independent)
if (!S.rg) {
  const RG = 200; S.rg = createGraphics(RG, RG); S.rg.noStroke();
  const gc = S.rg.drawingContext;
  const grd = gc.createRadialGradient(RG / 2, RG / 2, RG * 0.02, RG / 2, RG / 2, RG * 0.5);
  grd.addColorStop(0, 'rgba(255,255,255,1)');
  grd.addColorStop(0.35, 'rgba(150,150,150,1)');
  grd.addColorStop(1, 'rgba(6,6,6,1)');
  gc.fillStyle = grd; gc.fillRect(0, 0, RG, RG);
}

// full-canvas render buffer (cached on size)
if (!S.fb || S.fbKey !== width + 'x' + height) {
  S.fb = createGraphics(width, height); S.fb.pixelDensity(1);
  S.fb.colorMode(HSB, 360, 100, 100, 100); S.fbKey = width + 'x' + height;
}
const g = S.fb;

// ---- live parameters (drift on K.t; never re-phases) ----
const sec = K.section;
const isec = 0.4 + 0.6 * K.intensity;
const hb = wh(P.hue + S.hoff + sec * 16);
const eg = 0.45 + P.energy * 0.9;
const cx = width * P.x, cy = height * P.y;
const pump = 1 + A.bass * 0.12 + K.pulse * 0.05 * P.energy + K.swell * 0.03;
const R = u * (0.14 + 0.34 * P.scale) * pump;

const tt = K.t * (0.5 + P.speed * 0.5);
const nLive = P.petals + S.nEx + (0.5 + 0.6 * isec) * Math.sin(tt * 0.041 + S.nph) + 0.25 * Math.sin(tt * 0.017 + 1.3);
let dLive = P.step + S.dEx
  + (2.2 + 1.6 * P.speed + 3.4 * isec) * Math.sin(tt * 0.037 + S.dph1)
  + (1.4 + 2.0 * isec) * Math.sin(tt * 0.023 + S.dph2)
  + A.mid * 4;
if (dLive < 1.2 && dLive > -1.2) dLive = dLive < 0 ? -1.2 : 1.2;

// continuous whole-figure rotation (linear in K.t -> guaranteed non-re-phasing motion floor)
const rot = K.t * (0.05 + P.speed * 0.06) * S.spin + 0.15 * Math.sin(K.t * 0.05);

// ---- sample Maurer points (unit radius) ----
const N = Math.round(180 + P.density * 300);
const PX = (S.PX && S.PX.length > N) ? S.PX : (S.PX = new Float32Array(620));
const PY = (S.PY && S.PY.length > N) ? S.PY : (S.PY = new Float32Array(620));
for (let k = 0; k <= N; k++) {
  const th = k * dLive * DEG;
  const rr = Math.sin(nLive * th);
  PX[k] = rr * Math.cos(th);
  PY[k] = rr * Math.sin(th);
}

const bands = Math.min(30, Math.max(10, Math.round(N / 14)));
const glowStyle = (style === 'spectral' || style === 'gold' || style === 'neon');
function bandHue(b) {
  const f = b / bands;
  if (style === 'gold') return wh(36 + f * 30 + 6 * Math.sin(K.t * 0.25 + f * 6));
  if (style === 'neon') return wh(hb + ((Math.floor(f * 3) % 2 === 0) ? 0 : 155) + K.t * 7 * S.spin);
  return wh(hb + f * S.hueSpread + K.t * 6 * S.spin);
}

// ================= GROUND =================
g.push();
if (style === 'ink') g.background(38, 14, 90);
else if (style === 'blueprint') g.background(214, 78, 20);
else if (style === 'gold') g.background(32, 58, 8);
else if (style === 'neon') g.background(250, 42, 5);
else g.background(hb, 55, 9);
g.pop();

// ambient aura / vignette
const cov = Math.max(width, height) * 1.5;
g.push(); g.imageMode(CENTER);
if (style === 'ink') {
  g.blendMode(MULTIPLY); g.tint(36, 18, 100); g.image(S.rg, width / 2, height / 2, cov, cov); g.blendMode(BLEND);
} else if (style === 'blueprint') {
  g.blendMode(ADD); g.tint(205, 55, 24); g.image(S.rg, cx, cy, cov * 0.95, cov * 0.95); g.blendMode(BLEND);
} else {
  g.blendMode(ADD);
  const ah = style === 'gold' ? 42 : (style === 'neon' ? wh(hb + 8) : wh(hb));
  const asat = style === 'gold' ? 70 : (style === 'neon' ? 68 : 60);
  g.tint(ah, asat, 36 * (0.7 + 0.5 * isec) + A.rms * 24);
  g.image(S.rg, cx, cy, cov, cov);
  g.blendMode(BLEND);
}
g.pop();

// ================= FIGURE (rotated) =================
g.push();
g.translate(cx, cy);
g.rotate(rot);

// faint smooth rose beneath
const M = 220;
if (style === 'ink') { g.noStroke(); g.fill(32, 16, 32, 11); }
else if (style === 'blueprint') { g.noStroke(); g.fill(200, 45, 100, 6); }
else { g.blendMode(ADD); g.noStroke(); g.fill(wh(hb + 20), 72, 62, 7 + 6 * eg); }
g.beginShape();
for (let i = 0; i <= M; i++) {
  const th = (i / M) * TAU;
  const rr = Math.sin(nLive * th);
  g.vertex(rr * Math.cos(th) * R, rr * Math.sin(th) * R);
}
g.endShape(CLOSE);
g.blendMode(BLEND);

// glow underlay (translucent thick, ADD) for glow styles
if (glowStyle) {
  g.blendMode(ADD); g.noFill();
  const wG = (style === 'neon' ? 6.5 : 4.5) * (0.6 + eg * 0.7);
  for (let pass = 0; pass < 2; pass++) {
    const pw = pass === 0 ? wG : wG * 0.5;
    const pa = pass === 0 ? (style === 'neon' ? 7 : 5) : 11;
    for (let b = 0; b < bands; b++) {
      const si = Math.round(b * N / bands), ei = Math.round((b + 1) * N / bands);
      g.stroke(bandHue(b), style === 'gold' ? 66 : 84, 100, pa);
      g.strokeWeight(pw);
      g.beginShape();
      for (let k = si; k <= ei; k++) g.vertex(PX[k] * R, PY[k] * R);
      g.endShape();
    }
  }
}

// sharp Maurer polyline (per-band hue gradient along the walk)
g.blendMode(glowStyle ? ADD : BLEND);
g.noFill();
for (let b = 0; b < bands; b++) {
  const si = Math.round(b * N / bands), ei = Math.round((b + 1) * N / bands);
  const bh = bandHue(b);
  let sw;
  if (style === 'blueprint') { g.stroke(wh(198 + 8 * Math.sin(b)), 30, 100, 62); sw = 1.05; }
  else if (style === 'ink') {
    const dry = 0.5 + 0.5 * Math.sin(b * 1.7 + S.nph);
    g.stroke(30, 20, 10, 52 + 36 * dry); sw = 0.8 + 2.3 * dry;
  } else if (style === 'gold') { g.stroke(bh, 74, 100, 55 + A.treble * 30); sw = 1.1 + 0.9 * eg; }
  else if (style === 'neon') { g.stroke(bh, 92, 100, 60 + A.treble * 30); sw = 1.3 + 1.1 * eg; }
  else { g.stroke(bh, 78, 100, 55 + A.treble * 30); sw = 1.1 + 0.9 * eg; }
  if (glowStyle) {
    g.drawingContext.shadowBlur = (style === 'neon' ? 16 : 11) * (0.5 + eg);
    g.drawingContext.shadowColor = hcss(bh, style === 'gold' ? 60 : 72, 100, 0.85);
  }
  g.strokeWeight(sw);
  g.beginShape();
  for (let k = si; k <= ei; k++) g.vertex(PX[k] * R, PY[k] * R);
  g.endShape();
}
g.drawingContext.shadowBlur = 0;

// blueprint schematic furniture
if (style === 'blueprint') {
  g.blendMode(BLEND); g.noFill();
  g.stroke(200, 40, 100, 22); g.strokeWeight(0.7);
  const spokes = 12;
  for (let sp = 0; sp < spokes; sp++) { const a = sp / spokes * TAU; g.line(0, 0, R * 1.18 * Math.cos(a), R * 1.18 * Math.sin(a)); }
  g.stroke(200, 34, 100, 30); g.ellipse(0, 0, R * 2.35, R * 2.35);
  g.stroke(200, 30, 100, 20); g.ellipse(0, 0, R * 1.3, R * 1.3);
}

g.blendMode(BLEND);
g.pop();

// ================= CORE GLOW =================
if (glowStyle) {
  g.push(); g.blendMode(ADD); g.imageMode(CENTER);
  g.tint(wh(hb + (style === 'gold' ? 10 : 24)), style === 'gold' ? 55 : 50, 46 + A.rms * 30 + K.pulse * 10 * P.energy);
  const cc = u * (0.10 + 0.06 * P.scale) * (1 + K.pulse * 0.15 + A.bass * 0.25);
  g.image(S.rg, cx, cy, cc, cc);
  g.blendMode(BLEND); g.pop();
}

// ================= COMPOSITE =================
g.blendMode(BLEND);
push();
if (P.alpha < 100) tint(0, 0, 100, P.alpha);
image(g, 0, 0, width, height);
pop();
blendMode(BLEND);
